import org.junit.jupiter.api.AfterEach;import org.junit.jupiter.api.Assertions;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.Test;import org.openqa.selenium.By;import org.openqa.selenium.Cookie;import org.openqa.selenium.WebDriver;import org.openqa.selenium.chrome.ChromeDriver;import java.util.Set;public class CookiesTest{        WebDriver driver;    private static final String BASE_URL = "https://bonigarcia.dev/selenium-webdriver-java/";            @BeforeEach    void start () {                driver = new ChromeDriver();        driver.get(BASE_URL);    }        @AfterEach    void close () {                driver.close();    }        @Test    void getCookiesTest () {                driver.get(BASE_URL + "cookies.html");                WebDriver.Options options = driver.manage();                Set<Cookie> cookies  = options.getCookies();        Assertions.assertEquals(2, cookies.size());                Cookie nameUser = options.getCookieNamed("username");        Assertions.assertEquals("John Doe", nameUser.getValue());        Assertions.assertEquals("/", nameUser.getPath());                driver.findElement( By.id("refresh-cookies")).click();                Cookie newCookie = new Cookie("new-cookie-key", "new-cookie-value");        options.addCookie(newCookie);        String readCookie = options.getCookieNamed(newCookie.getName())                .getValue();                Assertions.assertEquals(readCookie, newCookie.getValue());                cookies = options.getCookies();        Assertions.assertEquals(3, cookies.size());                driver.findElement( By.id("refresh-cookies")).click();        options.deleteCookie(nameUser);                Assertions.assertEquals(2, cookies.size() - 1);                driver.findElement( By.id("refresh-cookies")).click();            }}